/* @autogenerated */
import { Shift } from '@shared/data/repository/repository.model';
import {
  TemplateVariableFilter,
  TemplateVariableProjection,
} from 'app/features/template/template-variable/model/template-variable.model';
import { FormControl } from '@angular/forms';
import { input, effect, Component, signal } from '@angular/core';
import { DisplayProvider } from '@shared/data/display-provider';
import { TemplateVariableRepository } from 'app/features/template/template-variable/repository/template-variable-repository.service';

@Component({
  selector: 'template-variable-view-list',
  templateUrl: './template-variable-view-list.component.html',
  styleUrls: ['./template-variable-view-list.component.scss'],
  standalone: false,
})
export class TemplateVariableViewListComponent {
  filters = input<TemplateVariableFilter>();
  actionName = input<string>('template-variable');
  fixed = input<{ [key: string]: any }>();
  hidden = input<{ [key: string]: any }>();
  search = new FormControl<any>(undefined);
  showSearchLabel = signal('Refresh');
  hideSearchLabel = signal('Refresh');
  list: Shift<TemplateVariableProjection[], TemplateVariableFilter>;
  displayer: DisplayProvider<any>;
  refreshDataLabel = signal('Refresh');
  /** Último filtro buscado, sin paginación: lo usa la exportación. */
  query = signal<TemplateVariableFilter>({});

  constructor(repository: TemplateVariableRepository) {
    this.displayer = repository.displayProvider();
    this.list = repository.projections(['tenant']);
    effect(() => {
      setTimeout(() => this.makeSearch());
    });
  }
  makeSearch() {
    const result = { limit: 10 } as any;
    const filter = this.search.value;
    const external = this.filters();
    if (external?.search) {
      result.search = external.search;
    }
    if (external?.code) {
      result.code = external.code;
    }
    if (external?.tenant) {
      result.tenant = external.tenant;
    }
    if (external?.tenants) {
      result.tenants = external.tenants;
    }
    if (filter?.search) {
      result.search = filter.search;
    }
    if (filter?.code) {
      result.code = filter.code;
    }
    if (filter?.tenant?.$ref) {
      result.tenant = filter.tenant.$ref;
    }
    if (filter?.tenants?.$ref) {
      result.tenants = filter.tenants.$ref;
    }
    if (filter?.order) {
      result.order = filter.order;
    }
    const { limit, ...query } = result;
    this.query.set(query);
    this.list.fetch(result);
  }

  next() {
    this.list.next();
  }

  reload() {
    this.list.reset();
  }

  prev() {
    console.log('PREV');
  }
}
